// Atlas pixels are generated by the actual P4 C++ renderer, not a second set
// of approximate JS drawing formulas. See firmware tools/check_p4_led.py.
(function (global) {
  "use strict";
  const decoded = new Map();
  function frame(atlas, effect, elapsedMs, params = {}) {
    const program = effect.program || {};
    const defaults = program.defaults || {};
    const settings = { ...(program.template ? { color: "#ffffff" } : {}), ...defaults, ...params };
    let key = effect.effect_id;
    if (program.template) {
      key = `template:${program.template}`;
      if (program.template === "mouth") key += `:${program.variant || "open"}`;
    }
    if (program.template === "arrow" || ["left", "right", "up", "down"].includes(key)) {
      key = settings.direction || (program.template ? "right" : key);
    }
    const clip = atlas.effects[key];
    if (!clip) throw new Error(`P4 预览缺少效果：${key}`);
    const tick = Math.floor(Math.max(0, elapsedMs) / 100) % atlas.ticks;
    const encoded = clip.frames[clip.timeline[tick]];
    if (!decoded.has(encoded)) {
      decoded.set(encoded, Uint8Array.from(atob(encoded), (value) => value.charCodeAt(0)));
    }
    const pixels = decoded.get(encoded);
    const intensity = Math.max(0.1, Math.min(1, Number(settings.intensity ?? 1)));
    const override = /^#[0-9a-f]{6}$/i.test(settings.color || "") ? settings.color : null;
    const palette = clip.palette.map(([color, primary]) => {
      const value = Number.parseInt((override && primary ? override : color).slice(1), 16);
      const level = override && primary ? primary / 255 : 1;
      const rgb = [16, 8, 0].map((shift) => Math.floor(((value >> shift) & 255) * level * intensity));
      return rgb.every((v) => v === 0) ? null : `#${rgb.map((v) => v.toString(16).padStart(2, "0")).join("")}`;
    });
    return Array.from(pixels, (index) => palette[index]);
  }
  global.P4LedPreview = { frame };
  if (typeof module !== "undefined") module.exports = global.P4LedPreview;
})(globalThis);
